package royalty

import (
	"chain"
	"math"
	"strconv"

	"gno.land/p/g1j4ehkkrqcr53a233wamtvqggt3skr86c6777xd/gnomads/grc721/v0"
)

const Kind = "royalty"

// NewRoyalty attaches a royalty extension; maxBps caps every rate and must be 0..10000.
func NewRoyalty(coreLedger *grc721.PrivateLedger, maxBps int64) (*Royalty, *Ledger) {
	if coreLedger == nil {
		panic("royalty: nil core ledger")
	}

	if maxBps < 0 || maxBps > FeeDenominator {
		panic(ErrMaxBpsRange)
	}

	st := &storage{maxBps: maxBps}
	core := coreLedger.ReadToken()
	led := &Ledger{core: core, st: st}

	coreLedger.RegisterExtension(led)

	return &Royalty{core: core, st: st}, led
}

func (r *Royalty) ExtensionKind() string { return Kind }

func (r *Royalty) TokenID() string { return r.core.ID() }

func (r *Royalty) MaxBps() int64 { return r.st.maxBps }

// RoyaltyInfo implements EIP-2981; per-token override takes precedence over the
// default, and no royalty returns (zeroAddress, 0) — the "no royalty" signal.
func (r *Royalty) RoyaltyInfo(tid grc721.TokenID, salePrice int64) (address, int64, error) {
	if salePrice < 0 {
		return zeroAddress, 0, ErrInvalidSalePrice
	}

	info, ok := r.resolve(tid)
	if !ok {
		return zeroAddress, 0, nil
	}

	if info.Bps != 0 && salePrice > math.MaxInt64/info.Bps {
		return zeroAddress, 0, ErrInvalidSalePrice
	}

	amount := salePrice * info.Bps / FeeDenominator

	return info.Receiver, amount, nil
}

func (r *Royalty) DefaultRoyalty() (RoyaltyInfo, bool) {
	if !r.st.hasDefault {
		return RoyaltyInfo{}, false
	}

	return r.st.def, true
}

func (r *Royalty) TokenRoyalty(tid grc721.TokenID) (RoyaltyInfo, bool) {
	v := r.st.perToken.Get(tid.String())
	if v == nil {
		return RoyaltyInfo{}, false
	}

	return v.(RoyaltyInfo), true
}

// resolve returns the effective royalty: per-token override first, then default.
func (r *Royalty) resolve(tid grc721.TokenID) (RoyaltyInfo, bool) {
	if v := r.st.perToken.Get(tid.String()); v != nil {
		return v.(RoyaltyInfo), true
	}

	if r.st.hasDefault {
		return r.st.def, true
	}

	return RoyaltyInfo{}, false
}

// SetDefaultRoyalty sets the collection default for tokens without an override; issuer-only.
func (led *Ledger) SetDefaultRoyalty(receiver address, bps int64) error {
	if err := led.validate(receiver, bps); err != nil {
		return err
	}

	led.st.def = RoyaltyInfo{Receiver: receiver, Bps: bps}
	led.st.hasDefault = true

	led.emitRoyaltyUpdate("default", "", receiver, bps)
	return nil
}

func (led *Ledger) DeleteDefaultRoyalty() {
	led.st.hasDefault = false
	led.st.def = RoyaltyInfo{}

	led.emitRoyaltyUpdate("default", "", zeroAddress, 0)
}

// SetTokenRoyalty sets a per-token override for tid; issuer-only.
func (led *Ledger) SetTokenRoyalty(tid grc721.TokenID, receiver address, bps int64) error {
	if _, err := led.core.OwnerOf(tid); err != nil {
		return ErrTokenNotMinted
	}

	if err := led.validate(receiver, bps); err != nil {
		return err
	}

	led.st.perToken.Set(tid.String(), RoyaltyInfo{Receiver: receiver, Bps: bps})

	led.emitRoyaltyUpdate("token", tid.String(), receiver, bps)
	return nil
}

// DeleteTokenRoyalty clears the per-token override, falling back to the default.
func (led *Ledger) DeleteTokenRoyalty(tid grc721.TokenID) {
	led.st.perToken.Remove(tid.String())

	led.emitRoyaltyUpdate("token", tid.String(), zeroAddress, 0)
}

// emitRoyaltyUpdate signals a royalty change (EIP-2981 defines no events); a
// cleared royalty is reported as an empty receiver and bps 0.
func (led *Ledger) emitRoyaltyUpdate(scope, tokenID string, receiver address, bps int64) {
	chain.Emit(
		RoyaltyUpdateEvent,
		"token", led.core.ID(),
		"scope", scope,
		"tokenId", tokenID,
		"receiver", receiver.String(),
		"bps", strconv.FormatInt(bps, 10),
	)
}

func (led *Ledger) validate(receiver address, bps int64) error {
	if !receiver.IsValid() {
		return ErrInvalidReceiver
	}

	if bps < 0 || bps > led.st.maxBps {
		return ErrInvalidBps
	}

	return nil
}

func (led *Ledger) ExtensionKind() string { return Kind }

func (led *Ledger) OnMint(to address, tid grc721.TokenID)           {}
func (led *Ledger) OnTransfer(from, to address, tid grc721.TokenID) {}

// OnBurn clears the per-token override (cannot resurface on re-mint) but keeps
// the default, which is collection-level policy, not per-token state.
func (led *Ledger) OnBurn(tid grc721.TokenID) {
	led.st.perToken.Remove(tid.String())
}

// Package royalty is a stackable GRC721 extension implementing EIP-2981 in basis
// points. Writes are issuer-only so a holder cannot zero out a royalty on a
// token they just received.
package royalty

import (
	"errors"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/g1j4ehkkrqcr53a233wamtvqggt3skr86c6777xd/gnomads/grc721/v0"
)

// FeeDenominator is the EIP-2981 basis-point denominator: bps/10000, 10000 == 100%.
const FeeDenominator = 10000

const RoyaltyUpdateEvent = "RoyaltyUpdate"

var (
	ErrInvalidReceiver  = errors.New("invalid royalty receiver")
	ErrInvalidBps       = errors.New("royalty bps out of range")
	ErrTokenNotMinted   = errors.New("token is not minted")
	ErrMaxBpsRange      = errors.New("maxBps out of range (0..10000)")
	ErrInvalidSalePrice = errors.New("invalid sale price (negative or would overflow)")
)

var zeroAddress = address("")

// RoyaltyInfo is a royalty policy: send Bps/10000 of a sale to Receiver.
type RoyaltyInfo struct {
	Receiver address
	Bps      int64
}

type storage struct {
	maxBps     int64
	hasDefault bool
	def        RoyaltyInfo
	perToken   avl.Tree // grc721.TokenID -> RoyaltyInfo
}

type Royalty struct {
	core *grc721.Token
	st   *storage
}

type Ledger struct {
	core *grc721.Token
	st   *storage
}

var _ grc721.Extension = (*Ledger)(nil)

var _ grc721.ExtensionView = (*Royalty)(nil)

package gnomads

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"crypto/sha256"
	"encoding/hex"
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

const maxMerkleProofDepth = 32

var (
	allowlistRoot       string
	allowlistRootLocked bool
)

func AllowlistRoot() string { return allowlistRoot }

func AllowlistRootLocked() bool { return allowlistRootLocked }

// SetAllowlistRoot accepts a lowercase/uppercase 32-byte SHA-256 hash in hex.
// The first sale unpause permanently locks the root for this deployment.
func SetAllowlistRoot(cur realm, root string) {
	assertAdmin(cur.Previous().Address())
	if !salePaused {
		panic("gnomads: pause sale before setting allowlist root")
	}
	if allowlistRootLocked {
		panic("gnomads: allowlist root is locked")
	}
	decoded, ok := decodeMerkleHash(root)
	if !ok || len(decoded) != sha256.Size {
		panic("gnomads: invalid allowlist root")
	}
	allowlistRoot = hex.EncodeToString(decoded)
	chain.Emit("AllowlistRootConfigured", "root", allowlistRoot)
}

// AllowlistLeaf binds a claim to this chain, collection, phase, address,
// individual allowance and configured unit price.
func AllowlistLeaf(owner address, allowance int, unitPrice int64) string {
	payload := runtime.ChainID() + "|" +
		CollectionID() + "|" +
		salePhaseAllowlist + "|" +
		owner.String() + "|" +
		ufmt.Sprintf("%d", allowance) + "|" +
		ufmt.Sprintf("%d", unitPrice)
	return hashBytes([]byte(payload))
}

// VerifyAllowlist expects comma-separated 64-character hex sibling hashes.
// Pair hashing is sorted, so proofs do not need left/right direction flags.
func VerifyAllowlist(owner address, allowance int, unitPrice int64, proof string) bool {
	if allowlistRoot == "" || allowance < 1 || allowance > maxSupplyAsInt() {
		return false
	}

	computed := AllowlistLeaf(owner, allowance, unitPrice)
	siblings, ok := parseMerkleProof(proof)
	if !ok {
		return false
	}
	for _, sibling := range siblings {
		computed = hashMerklePair(computed, sibling)
	}
	return computed == allowlistRoot
}

func MintAllowlist(cur realm, quantity, allowance int, unitPrice int64, proof string) {
	if !cur.Previous().IsUserCall() {
		panic("gnomads: only direct user calls can mint")
	}
	if SalePhase() != salePhaseAllowlist {
		panic("gnomads: allowlist sale is not active")
	}
	if unitPrice != saleConfig.allowlistPrice {
		panic("gnomads: allowlist price mismatch")
	}
	if allowance < 1 || allowance > saleConfig.allowlistLimit {
		panic("gnomads: invalid allowlist allowance")
	}

	caller := cur.Previous().Address()
	if !VerifyAllowlist(caller, allowance, unitPrice, proof) {
		panic("gnomads: invalid allowlist proof")
	}
	assertSaleMint(quantity, AllowlistMinted(caller), allowance)
	required := requiredPayment(unitPrice, quantity)
	sent := unsafe.OriginSend()
	assertExactPayment(sent, required)

	mintTokens(caller, quantity)
	allowlistMintedByWallet.Set(caller.String(), AllowlistMinted(caller)+quantity)
	forwardPayment(cur, sent)

	chain.Emit(
		"AllowlistMint",
		"minter", caller.String(),
		"quantity", ufmt.Sprintf("%d", quantity),
		"allowance", ufmt.Sprintf("%d", allowance),
		"paid", ufmt.Sprintf("%d", required),
	)
}

func parseMerkleProof(proof string) ([]string, bool) {
	if proof == "" {
		return []string{}, true
	}
	parts := strings.Split(proof, ",")
	if len(parts) > maxMerkleProofDepth {
		return nil, false
	}
	for i, part := range parts {
		decoded, ok := decodeMerkleHash(part)
		if !ok {
			return nil, false
		}
		parts[i] = hex.EncodeToString(decoded)
	}
	return parts, true
}

func hashMerklePair(first, second string) string {
	left, leftOK := decodeMerkleHash(first)
	right, rightOK := decodeMerkleHash(second)
	if !leftOK || !rightOK {
		return ""
	}
	if second < first {
		left, right = right, left
	}
	combined := make([]byte, 0, sha256.Size*2)
	combined = append(combined, left...)
	combined = append(combined, right...)
	return hashBytes(combined)
}

func hashBytes(data []byte) string {
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:])
}

func decodeMerkleHash(value string) ([]byte, bool) {
	if len(value) != sha256.Size*2 {
		return nil, false
	}
	decoded, err := hex.DecodeString(value)
	if err != nil || len(decoded) != sha256.Size {
		return nil, false
	}
	return decoded, true
}

func maxSupplyAsInt() int { return int(maxSupply) }

package gnomads

import (
	"gno.land/p/g1j4ehkkrqcr53a233wamtvqggt3skr86c6777xd/gnomads/grc721/enumerable/v0"
	"gno.land/p/g1j4ehkkrqcr53a233wamtvqggt3skr86c6777xd/gnomads/grc721/metadata/v0"
	"gno.land/p/g1j4ehkkrqcr53a233wamtvqggt3skr86c6777xd/gnomads/grc721/royalty/v0"
	"gno.land/p/g1j4ehkkrqcr53a233wamtvqggt3skr86c6777xd/gnomads/grc721/v0"
)

const (
	defaultRoyaltyBps = int64(500)  // 5%, matching the selected OpenSea-style policy.
	royaltyMaxBps     = int64(1000) // Permanent collection cap: 10%.
)

// Replace this value through SetVeiledURI before the first public mint.
// The explicit placeholder prevents an unfinished CID from looking production-ready.
var veiledURI = "ipfs://REPLACE_WITH_VEILED_METADATA_CID/metadata.json"

var (
	metadataView     *metadata.Metadata
	metadataLedger   *metadata.Ledger
	enumerableView   *enumerable.Enumerable
	enumerableLedger *enumerable.Ledger
	royaltyView      *royalty.Royalty
	royaltyLedger    *royalty.Ledger
)

// attachExtensions must run before the first mint so the enumerable index and
// metadata hooks observe every token from genesis.
func attachExtensions(coreLedger *grc721.PrivateLedger) {
	metadataView, metadataLedger = metadata.NewMetadata(coreLedger)
	enumerableView, enumerableLedger = enumerable.NewEnumerable(coreLedger)
	royaltyView, royaltyLedger = royalty.NewRoyalty(coreLedger, royaltyMaxBps)

	if err := royaltyLedger.SetDefaultRoyalty(localAdmin, defaultRoyaltyBps); err != nil {
		panic(err)
	}
}

// Metadata / veil facade.

func VeiledURI() string { return veiledURI }

func TokenURI(tokenID string) string {
	uri, err := metadataView.TokenURI(grc721.TokenID(tokenID))
	if err != nil {
		panic(err)
	}
	return uri
}

// SetVeiledURI allows the final placeholder CID to be configured once before
// minting begins. Existing token URIs are never silently rewritten.
func SetVeiledURI(cur realm, uri string) {
	assertAdmin(cur.Previous().Address())
	supply := token.TotalSupply()
	if !canConfigureVeiledURI(uri, supply) {
		if supply != 0 {
			panic("gnomads: veiled uri is locked after the first mint")
		}
		panic("gnomads: veiled uri cannot be empty")
	}
	veiledURI = uri
}

func validVeiledURI(uri string) bool { return uri != "" }

func canConfigureVeiledURI(uri string, supply int64) bool {
	return supply == 0 && validVeiledURI(uri)
}

func setInitialTokenURI(tokenID grc721.TokenID) {
	if err := metadataLedger.SetTokenURI(tokenID, veiledURI); err != nil {
		panic(err)
	}
}

// Enumerable facade.

func EnumerableSupply() int64 { return enumerableView.TotalSupply() }

func TokenByIndex(index int64) string {
	tokenID, err := enumerableView.TokenByIndex(index)
	if err != nil {
		panic(err)
	}
	return tokenID.String()
}

func TokenOfOwnerByIndex(owner address, index int64) string {
	tokenID, err := enumerableView.TokenOfOwnerByIndex(owner, index)
	if err != nil {
		panic(err)
	}
	return tokenID.String()
}

// Royalty facade. This is EIP-2981-style royalty information. Actual payment
// enforcement belongs in the project marketplace settlement realm.

func RoyaltyMaxBps() int64 { return royaltyView.MaxBps() }

func DefaultRoyalty() (address, int64) {
	info, ok := royaltyView.DefaultRoyalty()
	if !ok {
		return address(""), 0
	}
	return info.Receiver, info.Bps
}

func RoyaltyInfo(tokenID string, salePrice int64) (address, int64) {
	receiver, amount, err := royaltyView.RoyaltyInfo(grc721.TokenID(tokenID), salePrice)
	if err != nil {
		panic(err)
	}
	return receiver, amount
}

func SetDefaultRoyalty(cur realm, receiver address, bps int64) {
	assertAdmin(cur.Previous().Address())
	if !validRoyaltyBps(bps) {
		panic("gnomads: royalty bps out of range")
	}
	if err := royaltyLedger.SetDefaultRoyalty(receiver, bps); err != nil {
		panic(err)
	}
}

func validRoyaltyBps(bps int64) bool {
	return bps >= 0 && bps <= royaltyMaxBps
}

package gnomads

import (
	"gno.land/p/g1j4ehkkrqcr53a233wamtvqggt3skr86c6777xd/gnomads/grc721/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	collectionName   = "Gnomads"
	collectionSymbol = "GNOMADS"
	maxSupply        = int64(3333)
	maxMintBatch     = 20
)

// localAdmin is the standard prefunded gnodev account. It is intentionally
// limited to local development and must be replaced by the deployment owner
// before Pearl or Mainnet deployment.
const localAdmin address = "g1j4ehkkrqcr53a233wamtvqggt3skr86c6777xd"

var (
	token        *grc721.Token
	ledger       *grc721.PrivateLedger
	callerTeller grc721.Teller
)

func init(cur realm) {
	token, ledger = grc721.NewToken(collectionName, collectionSymbol, 0, cur)
	callerTeller = ledger.CallerTeller()
	attachExtensions(ledger)
}

// Collection getters.

func Status() string { return "REVEAL_ENGINE_READY" }

func Name() string { return token.GetName() }

func Symbol() string { return token.GetSymbol() }

func CollectionID() string { return token.ID() }

func TotalSupply() int64 { return token.TotalSupply() }

func MaxSupply() int64 { return maxSupply }

func Admin() address { return localAdmin }

// GRC-721 read facade.

func BalanceOf(owner address) int64 {
	balance, err := token.BalanceOf(owner)
	if err != nil {
		panic(err)
	}
	return balance
}

func OwnerOf(tokenID string) address {
	owner, err := token.OwnerOf(grc721.TokenID(tokenID))
	if err != nil {
		panic(err)
	}
	return owner
}

func GetApproved(tokenID string) address {
	approved, err := token.GetApproved(grc721.TokenID(tokenID))
	if err != nil {
		panic(err)
	}
	return approved
}

func IsApprovedForAll(owner, operator address) bool {
	return token.IsApprovedForAll(owner, operator)
}

// GRC-721 write facade. CallerTeller derives the acting account from the
// current cross-realm frame and keeps the PrivateLedger inside this realm.

func Approve(cur realm, to address, tokenID string) {
	if err := callerTeller.Approve(0, cur, to, grc721.TokenID(tokenID)); err != nil {
		panic(err)
	}
}

func SetApprovalForAll(cur realm, operator address, approved bool) {
	if err := callerTeller.SetApprovalForAll(0, cur, operator, approved); err != nil {
		panic(err)
	}
}

func TransferFrom(cur realm, from, to address, tokenID string) {
	if cur.Previous().Address() != from {
		panic("gnomads: operator transfers require marketplace settlement")
	}
	if err := callerTeller.TransferFrom(0, cur, from, to, grc721.TokenID(tokenID)); err != nil {
		panic(err)
	}
}

// AdminMint is for reserve/local-development minting and is permanently locked
// after the first sale activation to prevent post-sale rare-token allocation.
func AdminMint(cur realm, to address, quantity int) {
	assertAdmin(cur.Previous().Address())
	assertMintingAllowed()
	if !salePaused || allowlistRootLocked {
		panic("gnomads: admin mint is locked after sale activation")
	}
	mintTokens(to, quantity)
}

func mintTokens(to address, quantity int) {
	assertMintingAllowed()
	assertMintQuantity(quantity)
	if token.TotalSupply()+int64(quantity) > maxSupply {
		panic("gnomads: max supply reached")
	}
	for i := 0; i < quantity; i++ {
		nextID := token.TotalSupply() + 1
		tokenID := grc721.TokenID(ufmt.Sprintf("%d", nextID))
		if err := ledger.Mint(to, tokenID); err != nil {
			panic(err)
		}
		setInitialTokenURI(tokenID)
	}
}

func Render(path string) string {
	if path != "" {
		return "404\n"
	}

	out := token.RenderHome()
	out += ufmt.Sprintf("* **Maximum supply**: %d\n", maxSupply)
	out += ufmt.Sprintf("* **Sale phase**: %s\n", SalePhase())
	out += ufmt.Sprintf("* **Sale paused**: %t\n", SalePaused())
	out += ufmt.Sprintf("* **Status**: %s\n", Status())
	return out
}

func assertAdmin(caller address) {
	if !isAdmin(caller) {
		panic("gnomads: restricted access")
	}
}

func isAdmin(caller address) bool {
	return caller == localAdmin
}

func assertMintQuantity(quantity int) {
	if !validMintQuantity(quantity) {
		panic(ufmt.Sprintf("gnomads: quantity must be between 1 and %d", maxMintBatch))
	}
}

func validMintQuantity(quantity int) bool {
	return quantity >= 1 && quantity <= maxMintBatch
}

package gnomads

import (
	"chain"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/g1j4ehkkrqcr53a233wamtvqggt3skr86c6777xd/gnomads/grc721/v0"
	"gno.land/p/nt/ufmt/v0"
)

var (
	authorizedMarketplace address
	settledMarketNonces  avl.Tree
)

func AuthorizedMarketplace() address { return authorizedMarketplace }

// SetAuthorizedMarketplace is a one-time binding made before minting. Keeping
// the PrivateLedger and Token handle private prevents other approved operators
// from bypassing the official royalty settlement path.
func SetAuthorizedMarketplace(cur realm, marketplace address) {
	assertAdmin(cur.Previous().Address())
	if authorizedMarketplace.IsValid() {
		panic("gnomads: authorized marketplace is locked")
	}
	if !marketplace.IsValid() {
		panic("gnomads: invalid marketplace address")
	}
	if token.TotalSupply() != 0 || !salePaused {
		panic("gnomads: configure marketplace before minting and sale activation")
	}
	authorizedMarketplace = marketplace
	chain.Emit("MarketplaceAuthorized", "marketplace", marketplace.String())
}

// MarketplaceTransfer is the only operator-transfer route. The authorized
// market supplies its consumed listing nonce and gross price for audit events.
func MarketplaceTransfer(cur realm, seller, buyer address, tokenID string, grossPrice, nonce int64) {
	marketplace := cur.Previous().Address()
	if marketplace != authorizedMarketplace || !authorizedMarketplace.IsValid() {
		panic("gnomads: caller is not authorized marketplace")
	}
	if grossPrice < 1 || nonce < 1 {
		panic("gnomads: invalid marketplace settlement")
	}
	nonceKey := marketplace.String() + ":" + ufmt.Sprintf("%d", nonce)
	if settledMarketNonces.Has(nonceKey) {
		panic("gnomads: marketplace nonce already settled")
	}
	if OwnerOf(tokenID) != seller {
		panic("gnomads: marketplace seller is not token owner")
	}
	if !token.IsApprovedForAll(seller, marketplace) {
		panic("gnomads: marketplace operator approval required")
	}

	settledMarketNonces.Set(nonceKey, true)
	if err := ledger.TransferFrom(marketplace, seller, buyer, grc721.TokenID(tokenID)); err != nil {
		panic(err)
	}
	chain.Emit(
		"MarketplaceSettlementTransfer",
		"marketplace", marketplace.String(),
		"tokenId", tokenID,
		"seller", seller.String(),
		"buyer", buyer.String(),
		"grossPrice", ufmt.Sprintf("%d", grossPrice),
		"nonce", ufmt.Sprintf("%d", nonce),
	)
}

package gnomads

import (
	"chain"
	"chain/runtime"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1j4ehkkrqcr53a233wamtvqggt3skr86c6777xd/gnomads/grc721/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	revealStateVeiled         = "VEILED"
	revealStateCommitted      = "REVEAL_COMMITTED"
	revealStateRevealing      = "REVEALING"
	revealStateRevealed       = "REVEALED"
	revealStateUnveiledFrozen = "UNVEILED_FROZEN"
	maxRevealBatch            = 20
)

var (
	revealState       = revealStateVeiled
	provenanceRoot    string
	revealCommitment  string
	finalBaseURI      string
	revealDeadline    int64
	revealSeedHash    string
	permutationA      int64
	permutationB      int64
	revealTarget      int64
	revealProcessed   int64
)

func RevealState() string { return revealState }

func ProvenanceRoot() string { return provenanceRoot }

func RevealCommitment() string { return revealCommitment }

func FinalBaseURI() string { return finalBaseURI }

func RevealDeadline() int64 { return revealDeadline }

func RevealSeedHash() string { return revealSeedHash }

func RevealTarget() int64 { return revealTarget }

func RevealProcessed() int64 { return revealProcessed }

func RevealOverdue() bool {
	return revealState == revealStateCommitted && time.Now().Unix() > revealDeadline
}

// ConfigureReveal permanently commits provenance, secret hash and final URI
// layout before the first token can be minted.
func ConfigureReveal(cur realm, provenance, commitment, baseURI string, deadline int64) {
	assertAdmin(cur.Previous().Address())
	if revealState != revealStateVeiled {
		panic("gnomads: reveal configuration already committed")
	}
	if token.TotalSupply() != 0 || !salePaused {
		panic("gnomads: configure reveal before minting and sale activation")
	}
	normalizedProvenance := normalizeHash(provenance)
	if normalizedProvenance == "" {
		panic("gnomads: invalid provenance root")
	}
	normalizedCommitment := normalizeHash(commitment)
	if normalizedCommitment == "" {
		panic("gnomads: invalid reveal commitment")
	}
	if !validFinalBaseURI(baseURI) {
		panic("gnomads: final base uri must be ipfs/https and end with slash")
	}
	if deadline <= time.Now().Unix() {
		panic("gnomads: reveal deadline must be in the future")
	}

	provenanceRoot = normalizedProvenance
	revealCommitment = normalizedCommitment
	finalBaseURI = baseURI
	revealDeadline = deadline
	revealState = revealStateCommitted

	chain.Emit(
		"RevealConfigured",
		"provenance", provenanceRoot,
		"commitment", revealCommitment,
		"deadline", ufmt.Sprintf("%d", revealDeadline),
	)
}

// ComputeRevealCommitment is deterministic but production secrets should be
// committed with the offline helper, never exposed through a public RPC query.
func ComputeRevealCommitment(secret string) string {
	payload := runtime.ChainID() + "|" + CollectionID() + "|REVEAL|" + secret
	return hashBytes([]byte(payload))
}

// Reveal is permissionless after public sale end (or sold out). Knowledge of
// the committed secret is the authorization, enabling an emergency reveal.
func Reveal(secret string) {
	if revealState != revealStateCommitted {
		panic("gnomads: reveal is not committed")
	}
	if len(secret) < 8 || len(secret) > 256 {
		panic("gnomads: reveal secret length must be 8..256")
	}
	if !saleConfigured || (time.Now().Unix() < saleConfig.publicEnd && token.TotalSupply() < maxSupply) {
		panic("gnomads: public sale has not ended")
	}
	if ComputeRevealCommitment(secret) != revealCommitment {
		panic("gnomads: reveal secret does not match commitment")
	}
	if token.TotalSupply() == 0 {
		panic("gnomads: cannot reveal an empty collection")
	}

	revealSeedHash = hashBytes([]byte("GNOMADS|SEED|" + secret))
	permutationA = derivePermutationA(secret)
	permutationB = deriveSeedNumber("B", secret) % maxSupply
	revealTarget = token.TotalSupply()
	revealProcessed = 0
	revealState = revealStateRevealing

	chain.Emit(
		"RevealStarted",
		"seedHash", revealSeedHash,
		"target", ufmt.Sprintf("%d", revealTarget),
	)
}

// ApplyRevealBatch updates sequentially minted tokens. Anyone may execute the
// deterministic batch, so the project operator cannot block progress.
func ApplyRevealBatch(startTokenID int64, quantity int) {
	if revealState != revealStateRevealing {
		panic("gnomads: reveal batch is not active")
	}
	if quantity < 1 || quantity > maxRevealBatch {
		panic("gnomads: reveal batch quantity must be 1..20")
	}
	if startTokenID != revealProcessed+1 {
		panic("gnomads: reveal batch must continue sequentially")
	}
	end := startTokenID + int64(quantity) - 1
	if end > revealTarget {
		panic("gnomads: reveal batch exceeds target")
	}

	for tokenID := startTokenID; tokenID <= end; tokenID++ {
		metadataID := MetadataID(tokenID)
		uri := finalBaseURI + metadataFilename(metadataID)
		if err := metadataLedger.SetTokenURI(grc721.TokenID(ufmt.Sprintf("%d", tokenID)), uri); err != nil {
			panic(err)
		}
	}
	revealProcessed = end
	if revealProcessed == revealTarget {
		revealState = revealStateRevealed
	}

	chain.Emit(
		"RevealBatchApplied",
		"startTokenId", ufmt.Sprintf("%d", startTokenID),
		"endTokenId", ufmt.Sprintf("%d", end),
		"processed", ufmt.Sprintf("%d", revealProcessed),
	)
}

// metadataFilename matches the immutable IPFS release layout (0001.json–3333.json).
func metadataFilename(metadataID int64) string {
	serial := ufmt.Sprintf("%d", metadataID)
	for len(serial) < 4 {
		serial = "0" + serial
	}
	return serial + ".json"
}

func MetadataID(tokenID int64) int64 {
	if revealState != revealStateRevealing &&
		revealState != revealStateRevealed &&
		revealState != revealStateUnveiledFrozen {
		panic("gnomads: metadata mapping is not revealed")
	}
	if tokenID < 1 || tokenID > revealTarget {
		panic("gnomads: token id outside reveal target")
	}
	return (permutationA*(tokenID-1)+permutationB)%maxSupply + 1
}

func FreezeMetadata(cur realm) {
	assertAdmin(cur.Previous().Address())
	if revealState != revealStateRevealed || revealProcessed != revealTarget {
		panic("gnomads: complete reveal before freezing metadata")
	}
	revealState = revealStateUnveiledFrozen
	chain.Emit("MetadataFrozen", "provenance", provenanceRoot, "seedHash", revealSeedHash)
}

func assertMintingAllowed() {
	if revealState != revealStateVeiled && revealState != revealStateCommitted {
		panic("gnomads: minting is closed after reveal starts")
	}
}

func validFinalBaseURI(uri string) bool {
	return (strings.HasPrefix(uri, "ipfs://") || strings.HasPrefix(uri, "https://")) &&
		strings.HasSuffix(uri, "/")
}

func derivePermutationA(secret string) int64 {
	candidate := deriveSeedNumber("A", secret) % maxSupply
	if candidate == 0 {
		candidate = 1
	}
	for gcd(candidate, maxSupply) != 1 {
		candidate++
		if candidate >= maxSupply {
			candidate = 1
		}
	}
	return candidate
}

func deriveSeedNumber(label, secret string) int64 {
	hash := hashBytes([]byte("GNOMADS|PERMUTATION|" + label + "|" + secret))
	value, err := strconv.ParseInt(hash[:15], 16, 64)
	if err != nil {
		panic(err)
	}
	return value
}

func gcd(first, second int64) int64 {
	for second != 0 {
		first, second = second, first%second
	}
	return first
}

func normalizeHash(value string) string {
	decoded, err := hex.DecodeString(value)
	if err != nil || len(decoded) != sha256.Size {
		return ""
	}
	return hex.EncodeToString(decoded)
}

package gnomads

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	salePhaseClosed    = "CLOSED"
	salePhaseAllowlist = "ALLOWLIST"
	salePhasePublic    = "PUBLIC"
	saleDenom          = "ugnot"
)

type saleConfiguration struct {
	allowlistStart int64
	allowlistEnd   int64
	publicStart    int64
	publicEnd      int64
	allowlistPrice int64
	publicPrice    int64
	allowlistLimit int
	publicLimit    int
	treasury       address
}

var (
	saleConfig              saleConfiguration
	saleConfigured          bool
	salePaused              = true
	allowlistMintedByWallet avl.Tree
	publicMintedByWallet    avl.Tree
)

// ConfigureSale stores timestamps as Unix seconds and prices in ugnot.
// Configuration is only mutable while the sale is paused.
func ConfigureSale(
	cur realm,
	allowlistStart, allowlistEnd int64,
	publicStart, publicEnd int64,
	allowlistPrice, publicPrice int64,
	allowlistLimit, publicLimit int,
	treasury address,
) {
	assertAdmin(cur.Previous().Address())
	if !salePaused {
		panic("gnomads: pause sale before configuration")
	}
	if !validSaleSchedule(allowlistStart, allowlistEnd, publicStart, publicEnd) {
		panic("gnomads: invalid sale schedule")
	}
	if !validSalePrice(allowlistPrice) || !validSalePrice(publicPrice) {
		panic("gnomads: invalid sale price")
	}
	if !validWalletLimit(allowlistLimit) || !validWalletLimit(publicLimit) {
		panic("gnomads: invalid wallet limit")
	}
	if !treasury.IsValid() {
		panic("gnomads: invalid sale treasury")
	}

	saleConfig = saleConfiguration{
		allowlistStart: allowlistStart,
		allowlistEnd:   allowlistEnd,
		publicStart:    publicStart,
		publicEnd:      publicEnd,
		allowlistPrice: allowlistPrice,
		publicPrice:    publicPrice,
		allowlistLimit: allowlistLimit,
		publicLimit:    publicLimit,
		treasury:       treasury,
	}
	saleConfigured = true

	chain.Emit(
		"SaleConfigured",
		"allowlistStart", ufmt.Sprintf("%d", allowlistStart),
		"allowlistEnd", ufmt.Sprintf("%d", allowlistEnd),
		"publicStart", ufmt.Sprintf("%d", publicStart),
		"publicEnd", ufmt.Sprintf("%d", publicEnd),
		"treasury", treasury.String(),
	)
}

func SetSalePaused(cur realm, paused bool) {
	assertAdmin(cur.Previous().Address())
	if !paused && !saleConfigured {
		panic("gnomads: configure sale before unpausing")
	}
	if !paused && allowlistRoot == "" {
		panic("gnomads: configure allowlist root before unpausing")
	}
	if !paused && revealState != revealStateCommitted {
		panic("gnomads: commit reveal configuration before unpausing")
	}
	if !paused {
		allowlistRootLocked = true
	}
	salePaused = paused
	chain.Emit("SalePauseChanged", "paused", ufmt.Sprintf("%t", paused))
}

func SalePhase() string { return salePhaseAt(time.Now().Unix()) }

func SalePhaseAt(unixTime int64) string { return salePhaseAt(unixTime) }

func salePhaseAt(unixTime int64) string {
	if salePaused || !saleConfigured {
		return salePhaseClosed
	}
	if unixTime >= saleConfig.allowlistStart && unixTime < saleConfig.allowlistEnd {
		return salePhaseAllowlist
	}
	if unixTime >= saleConfig.publicStart && unixTime < saleConfig.publicEnd {
		return salePhasePublic
	}
	return salePhaseClosed
}

func SalePaused() bool { return salePaused }

func SaleConfigured() bool { return saleConfigured }

func SaleTreasury() address { return saleConfig.treasury }

func AllowlistStart() int64 { return saleConfig.allowlistStart }

func AllowlistEnd() int64 { return saleConfig.allowlistEnd }

func PublicStart() int64 { return saleConfig.publicStart }

func PublicEnd() int64 { return saleConfig.publicEnd }

func AllowlistPrice() int64 { return saleConfig.allowlistPrice }

func PublicPrice() int64 { return saleConfig.publicPrice }

func AllowlistWalletLimit() int { return saleConfig.allowlistLimit }

func PublicWalletLimit() int { return saleConfig.publicLimit }

func AllowlistMinted(owner address) int { return mintedCount(&allowlistMintedByWallet, owner) }

func PublicMinted(owner address) int { return mintedCount(&publicMintedByWallet, owner) }

func NextSaleTimestamp() int64 {
	now := time.Now().Unix()
	if !saleConfigured {
		return 0
	}
	if now < saleConfig.allowlistStart {
		return saleConfig.allowlistStart
	}
	if now < saleConfig.allowlistEnd {
		return saleConfig.allowlistEnd
	}
	if now < saleConfig.publicStart {
		return saleConfig.publicStart
	}
	if now < saleConfig.publicEnd {
		return saleConfig.publicEnd
	}
	return 0
}

// MintPublic accepts only direct Adena/EOA calls. This pairing is critical:
// OriginSend describes actual receipt by this realm only for a direct user call.
func MintPublic(cur realm, quantity int) {
	if !cur.Previous().IsUserCall() {
		panic("gnomads: only direct user calls can mint")
	}
	if SalePhase() != salePhasePublic {
		panic("gnomads: public sale is not active")
	}

	caller := cur.Previous().Address()
	assertSaleMint(quantity, PublicMinted(caller), saleConfig.publicLimit)
	required := requiredPayment(saleConfig.publicPrice, quantity)
	sent := unsafe.OriginSend()
	assertExactPayment(sent, required)

	mintTokens(caller, quantity)
	publicMintedByWallet.Set(caller.String(), PublicMinted(caller)+quantity)
	forwardPayment(cur, sent)

	chain.Emit(
		"PublicMint",
		"minter", caller.String(),
		"quantity", ufmt.Sprintf("%d", quantity),
		"paid", ufmt.Sprintf("%d", required),
	)
}

func assertSaleMint(quantity, alreadyMinted, walletLimit int) {
	assertMintQuantity(quantity)
	if alreadyMinted+quantity > walletLimit {
		panic("gnomads: wallet mint limit exceeded")
	}
}

func requiredPayment(unitPrice int64, quantity int) int64 {
	if !validSalePrice(unitPrice) || !validMintQuantity(quantity) {
		panic("gnomads: invalid payment calculation")
	}
	return unitPrice * int64(quantity)
}

func assertExactPayment(sent chain.Coins, required int64) {
	if !isExactPayment(sent, required) {
		panic(ufmt.Sprintf("gnomads: exact payment required: %dugnot", required))
	}
}

func isExactPayment(sent chain.Coins, required int64) bool {
	return len(sent) == 1 && sent[0].Denom == saleDenom && sent[0].Amount == required
}

func forwardPayment(cur realm, sent chain.Coins) {
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), saleConfig.treasury, sent)
}

func mintedCount(tree *avl.Tree, owner address) int {
	v := tree.Get(owner.String())
	if v == nil {
		return 0
	}
	return v.(int)
}

func validSaleSchedule(allowlistStart, allowlistEnd, publicStart, publicEnd int64) bool {
	return allowlistStart > 0 &&
		allowlistStart < allowlistEnd &&
		allowlistEnd <= publicStart &&
		publicStart < publicEnd
}

func validSalePrice(price int64) bool {
	return price > 0 && price <= 9223372036854775807/int64(maxMintBatch)
}

func validWalletLimit(limit int) bool {
	return limit > 0 && int64(limit) <= maxSupply
}

package gnomads_market

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"math"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1j4ehkkrqcr53a233wamtvqggt3skr86c6777xd/gnomads"
)

const (
	marketDenom          = "ugnot"
	feeDenominator       = int64(10000)
	defaultProtocolFeeBps = int64(100) // 1%
	protocolFeeMaxBps     = int64(1000)
	maxListingPrice       = int64(math.MaxInt64 / protocolFeeMaxBps)
)

// Replace this local-development owner before Pearl or Mainnet deployment.
const localMarketAdmin address = "g1j4ehkkrqcr53a233wamtvqggt3skr86c6777xd"

type listing struct {
	seller            address
	price             int64
	expiresAt         int64
	nonce             int64
	royaltyReceiver   address
	royaltyAmount     int64
	protocolReceiver  address
	protocolFeeAmount int64
	sellerProceeds    int64
}

var (
	marketAddress      address
	listings           avl.Tree
	listingNonce       int64
	marketPaused       bool
	protocolFeeBps     = defaultProtocolFeeBps
	protocolTreasury   = localMarketAdmin
)

func init(cur realm) {
	marketAddress = cur.Address()
}

func Status() string { return "MARKETPLACE_READY" }

func Address() address { return marketAddress }

func CollectionID() string { return gnomads.CollectionID() }

func MarketPaused() bool { return marketPaused }

func ProtocolFeeBps() int64 { return protocolFeeBps }

func ProtocolTreasury() address { return protocolTreasury }

func ListingCount() int { return listings.Size() }

func HasListing(tokenID string) bool { return listings.Has(tokenID) }

func ListingSeller(tokenID string) address { return mustListing(tokenID).seller }

func ListingPrice(tokenID string) int64 { return mustListing(tokenID).price }

func ListingExpiry(tokenID string) int64 { return mustListing(tokenID).expiresAt }

func ListingNonce(tokenID string) int64 { return mustListing(tokenID).nonce }

func ListingRoyalty(tokenID string) (address, int64) {
	l := mustListing(tokenID)
	return l.royaltyReceiver, l.royaltyAmount
}

func ListingProtocolFee(tokenID string) (address, int64) {
	l := mustListing(tokenID)
	return l.protocolReceiver, l.protocolFeeAmount
}

func ListingSellerProceeds(tokenID string) int64 { return mustListing(tokenID).sellerProceeds }

// ConfigureProtocol affects new listings only. Existing listings retain the
// exact receiver and fee amounts shown when their seller created the order.
func ConfigureProtocol(cur realm, treasury address, feeBps int64) {
	assertMarketAdmin(cur.Previous().Address())
	if !treasury.IsValid() {
		panic("gnomads_market: invalid protocol treasury")
	}
	if feeBps < 0 || feeBps > protocolFeeMaxBps {
		panic("gnomads_market: protocol fee bps out of range")
	}
	protocolTreasury = treasury
	protocolFeeBps = feeBps
	chain.Emit(
		"ProtocolConfigured",
		"treasury", treasury.String(),
		"feeBps", ufmt.Sprintf("%d", feeBps),
	)
}

func SetMarketPaused(cur realm, paused bool) {
	assertMarketAdmin(cur.Previous().Address())
	marketPaused = paused
	chain.Emit("MarketPauseChanged", "paused", ufmt.Sprintf("%t", paused))
}

// List creates a non-custodial fixed-price order. The seller must first call
// Gnomads.SetApprovalForAll(Address(), true). Fee terms are snapshotted here.
func List(cur realm, tokenID string, price, expiresAt int64) {
	assertDirectUserCall(cur)
	if marketPaused {
		panic("gnomads_market: marketplace is paused")
	}
	if HasListing(tokenID) {
		panic("gnomads_market: token is already listed")
	}
	if price < 1 || price > maxListingPrice {
		panic("gnomads_market: invalid listing price")
	}
	if expiresAt != 0 && expiresAt <= time.Now().Unix() {
		panic("gnomads_market: listing expiry must be in the future")
	}

	seller := cur.Previous().Address()
	if gnomads.OwnerOf(tokenID) != seller {
		panic("gnomads_market: caller is not token owner")
	}
	if !gnomads.IsApprovedForAll(seller, Address()) {
		panic("gnomads_market: marketplace operator approval required")
	}

	royaltyReceiver, royaltyAmount := gnomads.RoyaltyInfo(tokenID, price)
	protocolAmount := calculateFee(price, protocolFeeBps)
	if royaltyAmount < 0 || royaltyAmount+protocolAmount > price {
		panic("gnomads_market: fees exceed listing price")
	}

	listingNonce++
	l := &listing{
		seller:            seller,
		price:             price,
		expiresAt:         expiresAt,
		nonce:             listingNonce,
		royaltyReceiver:   royaltyReceiver,
		royaltyAmount:     royaltyAmount,
		protocolReceiver:  protocolTreasury,
		protocolFeeAmount: protocolAmount,
		sellerProceeds:    price - royaltyAmount - protocolAmount,
	}
	listings.Set(tokenID, l)

	chain.Emit(
		"Listed",
		"tokenId", tokenID,
		"seller", seller.String(),
		"price", ufmt.Sprintf("%d", price),
		"expiresAt", ufmt.Sprintf("%d", expiresAt),
		"nonce", ufmt.Sprintf("%d", l.nonce),
	)
}

func Cancel(cur realm, tokenID string) {
	assertDirectUserCall(cur)
	l := mustListing(tokenID)
	if cur.Previous().Address() != l.seller {
		panic("gnomads_market: only seller can cancel listing")
	}
	listings.Remove(tokenID)
	chain.Emit("ListingCancelled", "tokenId", tokenID, "nonce", ufmt.Sprintf("%d", l.nonce))
}

// Invalidate removes an expired order, or an order whose owner/approval changed.
// Anyone may clear such an order because it can no longer settle as written.
func Invalidate(tokenID string) {
	l := mustListing(tokenID)
	if listingExecutable(tokenID, l) {
		panic("gnomads_market: listing is still executable")
	}
	listings.Remove(tokenID)
	chain.Emit("ListingInvalidated", "tokenId", tokenID, "nonce", ufmt.Sprintf("%d", l.nonce))
}

// Buy accepts only direct Adena/EOA calls so OriginSend describes coins that
// actually arrived at this realm. Transfer and all payouts roll back together.
func Buy(cur realm, tokenID string) {
	assertDirectUserCall(cur)
	if marketPaused {
		panic("gnomads_market: marketplace is paused")
	}
	l := mustListing(tokenID)
	if !listingExecutable(tokenID, l) {
		panic("gnomads_market: listing is stale or expired")
	}

	buyer := cur.Previous().Address()
	if buyer == l.seller {
		panic("gnomads_market: seller cannot buy own listing")
	}
	sent := unsafe.OriginSend()
	assertExactMarketPayment(sent, l.price)

	// Checks-effects-interactions: consume the one-time order before transfer and
	// payout. A panic still rolls the entire transaction back atomically.
	listings.Remove(tokenID)
	gnomads.MarketplaceTransfer(cross(cur), l.seller, buyer, tokenID, l.price, l.nonce)

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	pay(cur, b, l.seller, l.sellerProceeds)
	pay(cur, b, l.royaltyReceiver, l.royaltyAmount)
	pay(cur, b, l.protocolReceiver, l.protocolFeeAmount)

	chain.Emit(
		"Purchased",
		"tokenId", tokenID,
		"seller", l.seller.String(),
		"buyer", buyer.String(),
		"price", ufmt.Sprintf("%d", l.price),
		"royalty", ufmt.Sprintf("%d", l.royaltyAmount),
		"protocolFee", ufmt.Sprintf("%d", l.protocolFeeAmount),
		"sellerProceeds", ufmt.Sprintf("%d", l.sellerProceeds),
		"nonce", ufmt.Sprintf("%d", l.nonce),
	)
}

func Render(path string) string {
	if path != "" {
		return "404\n"
	}
	return "# Gnomads Marketplace\n\n" +
		ufmt.Sprintf("* **Collection**: %s\n", CollectionID()) +
		ufmt.Sprintf("* **Listings**: %d\n", ListingCount()) +
		ufmt.Sprintf("* **Protocol fee**: %d bps\n", ProtocolFeeBps()) +
		ufmt.Sprintf("* **Paused**: %t\n", MarketPaused())
}

func mustListing(tokenID string) *listing {
	v := listings.Get(tokenID)
	if v == nil {
		panic("gnomads_market: listing not found")
	}
	return v.(*listing)
}

func listingExecutable(tokenID string, l *listing) bool {
	if l.expiresAt != 0 && time.Now().Unix() >= l.expiresAt {
		return false
	}
	if gnomads.OwnerOf(tokenID) != l.seller {
		return false
	}
	return gnomads.IsApprovedForAll(l.seller, Address())
}

func calculateFee(price, bps int64) int64 {
	if price < 0 || bps < 0 || bps > protocolFeeMaxBps || (bps != 0 && price > math.MaxInt64/bps) {
		panic("gnomads_market: invalid fee calculation")
	}
	return price * bps / feeDenominator
}

func assertExactMarketPayment(sent chain.Coins, required int64) {
	if len(sent) != 1 || sent[0].Denom != marketDenom || sent[0].Amount != required {
		panic(ufmt.Sprintf("gnomads_market: exact payment required: %dugnot", required))
	}
}

func pay(cur realm, b banker.Banker, to address, amount int64) {
	if amount == 0 {
		return
	}
	b.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin(marketDenom, amount)))
}

func assertDirectUserCall(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("gnomads_market: only direct user calls are accepted")
	}
}

func assertMarketAdmin(caller address) {
	if caller != localMarketAdmin {
		panic("gnomads_market: restricted access")
	}
}
